var labels = ["Jul 24","Jul 27","Jul 28","Jul 29","Jul 30","Jul 31","Aug 4","Aug 5","Aug 6","Aug 7","Aug 10","Aug 11","Aug 12","Aug 13","Aug 14","Aug 17","Aug 18","Aug 19","Aug 20","Aug 21","Aug 24","Aug 25"];
var data = [35369.10,35568.14,35749.70,35333.78,35505.84,35226.14,35801.59,36146.42,36136.31,36381.23,36458.33,36475.92,36662.14,36759.29,36730.27,36667.92,36367.93,36401.79,36365.42,36620.23,36714.12,36957.63];
var n = data.length;

var yMin = 35000, yMax = 37200;
var xp = function(i){ return margin.left + i*(PW/(n-1)); };
var yp = function(v){ return margin.top + PH*(yMax-v)/(yMax-yMin); };

[35500,36000,36500,37000].forEach(function(g){
  svg.appendChild(el("line",{x1:margin.left, x2:margin.left+PW, y1:yp(g), y2:yp(g), stroke:"#ececec","stroke-width":"0.5"}));
});

// event marker: Aug 25 record close on bank earnings (index 21)
var evX = xp(21);
svg.appendChild(el("line",{x1:evX, x2:evX, y1:margin.top, y2:margin.top+PH, stroke:"#1a3560", "stroke-opacity":"0.5","stroke-dasharray":"2,3"}));
svg.appendChild(el("text",{x:evX-3, y:margin.top+12, "text-anchor":"end","font-size":"7","font-weight":"700",fill:"#1a3560","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}, "RECORD ON BANK EARNINGS"));

var d = "";
for (var i=0;i<n;i++){
  d += (i===0?"M":"L") + xp(i) + "," + yp(data[i]) + " ";
}
svg.appendChild(el("path",{d:d, fill:"none", stroke:"#3a7a55","stroke-width":"1.6"}));

svg.appendChild(el("line",{x1:margin.left, x2:margin.left+PW, y1:margin.top+PH, y2:margin.top+PH, stroke:"#d8d8d8","stroke-width":"1"}));

var lastX = xp(n-1), lastY = yp(data[n-1]);
svg.appendChild(el("circle",{cx:lastX, cy:lastY, r:4, fill:"#3a7a55"}));

[35500,36000,36500,37000].forEach(function(v){
  svg.appendChild(el("text",{x:margin.left-6, y:yp(v)+3, "text-anchor":"end","font-size":"8.5",fill:"#aaaaaa","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}, (v/1000).toFixed(1)+"k"));
});

[0,4,9,14,19,21].forEach(function(i){
  svg.appendChild(el("text",{x:xp(i), y:margin.top+PH+16, "text-anchor":"middle","font-size":"8",fill:"#999999","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}, labels[i]));
});

var pillText = data[n-1].toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:2});
var pillW = Math.ceil(pillText.length*9*0.58)+10;
var pillH = 16;
var pillX = lastX - pillW - 6;
if (pillX < margin.left) pillX = margin.left;
var pillY = lastY - pillH/2;
svg.appendChild(el("rect",{x:pillX, y:pillY, width:pillW, height:pillH, rx:3, fill:"#e8a825"}));
svg.appendChild(el("text",{x:pillX+pillW/2, y:pillY+pillH/2+4, "text-anchor":"middle","font-size":"9","font-weight":"700",fill:"#111111","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}, pillText));

_cs.parentNode.appendChild(svg);
})();
</script>
